<template><section class="scr-card"><div class="scr-form-grid"><label>{{ t('garage.left') }}<select v-model="left"><option value=""></option><option v-for="entry in entries" :key="entry.id" :value="entry.id">{{ entry.name }}</option></select></label><label>{{ t('garage.right') }}<select v-model="right"><option value=""></option><option v-for="entry in entries" :key="entry.id" :value="entry.id">{{ entry.name }}</option></select></label></div><button type="button" :disabled="!left || !right || left === right" @click="compare">{{ t('garage.compareAction') }}</button><div v-if="comparison" class="scr-diff-list"><strong>{{ comparison.equal ? 'equal' : `${comparison.differenceCount || comparison.differences?.length || 0} differences` }}</strong><div v-for="difference in comparison.differences || []" :key="`${difference.section}:${difference.path}`"><code>{{ difference.section }}.{{ difference.path }}</code><span>{{ display(difference.left) }} → {{ display(difference.right) }}</span></div></div></section></template>
<script setup>import { computed, ref } from "vue"; import { useStores } from "../../stores/index.js"; const stores = useStores(); const { t } = stores.i18n; const left = ref(""); const right = ref(""); const entries = computed(() => stores.garage.state.entries || []); const comparison = computed(() => stores.garage.state.comparison); const compare = () => stores.command.send("compareVehicleDNA", [left.value, right.value]); const display = value => typeof value === "object" ? JSON.stringify(value) : String(value ?? "—")</script>
